#!/bin/bash
# Cinammon · Vite / Apps JavaScript · instalación
# Prepara app/ (tu proyecto), el arranque y un servidor estático propio. Las dependencias
# (npm install) y la compilación se hacen al arrancar, con Node dentro del contenedor.
set -e
mkdir -p /mnt/server && cd /mnt/server
apt-get update -qq >/dev/null && apt-get install -y -qq git ca-certificates >/dev/null
mkdir -p app .cinammon logs

# ── Servidor estático (sin dependencias): sirve la carpeta compilada con soporte para SPA ──
cat > .cinammon/static.mjs <<'CIN_STATIC_EOF'
// Cinammon · servidor estático para apps compiladas (Vite, React, Vue, Svelte, Astro estático…)
import { createServer } from 'node:http';
import { createReadStream, statSync, existsSync } from 'node:fs';
import { extname, join, normalize, resolve, sep } from 'node:path';

const root = resolve(process.argv[2] || 'dist');
const port = Number(process.env.SERVER_PORT || process.argv[3] || 8080);
const spa = process.env.SPA_FALLBACK !== '0';
const types = {
  '.html': 'text/html; charset=utf-8', '.htm': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg', '.gif': 'image/gif', '.webp': 'image/webp', '.avif': 'image/avif', '.ico': 'image/x-icon',
  '.woff': 'font/woff', '.woff2': 'font/woff2', '.ttf': 'font/ttf', '.otf': 'font/otf', '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8', '.webmanifest': 'application/manifest+json', '.wasm': 'application/wasm',
  '.mp4': 'video/mp4', '.webm': 'video/webm', '.mp3': 'audio/mpeg', '.pdf': 'application/pdf',
};

const fileFor = (urlPath) => {
  let p;
  try { p = decodeURIComponent(urlPath.split('?')[0]); } catch { return null; }
  const full = normalize(join(root, p));
  if (full !== root && !full.startsWith(root + sep)) return null; // nada fuera de la carpeta
  for (const c of [full, join(full, 'index.html'), full + '.html']) {
    try { if (statSync(c).isFile()) return c; } catch {}
  }
  return null;
};

createServer((req, res) => {
  let file = fileFor(req.url || '/');
  let status = 200;
  if (!file) {
    const index = join(root, 'index.html');
    const page404 = join(root, '404.html');
    if (existsSync(page404)) { file = page404; status = 404; }
    else if (spa && existsSync(index) && !extname((req.url || '').split('?')[0])) file = index;
    else { res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' }); return res.end('404 · No encontrado'); }
  }
  const type = types[extname(file).toLowerCase()] || 'application/octet-stream';
  const hashed = /[.-][A-Za-z0-9_-]{8,}\.(js|css|woff2?|png|jpe?g|svg|webp|avif)$/.test(file);
  res.writeHead(status, {
    'Content-Type': type,
    'Cache-Control': hashed ? 'public, max-age=31536000, immutable' : 'no-cache',
    'X-Content-Type-Options': 'nosniff',
  });
  if (req.method === 'HEAD') return res.end();
  createReadStream(file).on('error', () => res.end()).pipe(res);
}).listen(port, '0.0.0.0', () => {
  console.log(`  ● Web en línea · sirviendo ${root} en el puerto ${port}`);
});
CIN_STATIC_EOF

# ── Arranque ──
rm -f start.sh
cat > start.sh <<'CIN_START_EOF'
#!/bin/bash
# Cinammon · Vite / Apps JavaScript · arranque
P='\033[1;35m'; C='\033[1;36m'; G='\033[0;32m'; Y='\033[1;33m'; R='\033[0;31m'; D='\033[2m'; N='\033[0m'
ok()   { echo -e "${G}  ✔ $1${N}"; }
warn() { echo -e "${Y}  ⚠ $1${N}"; }
fail() { echo -e "${R}  ✖ $1${N}"; }

echo -e "${P}"
echo -e "   ╔═════════════════════════════════════╗"
echo -e "   ║    ${C}C I N A M M O N${P}  ·  JS APPS     ║"
echo -e "   ╚═════════════════════════════════════╝${N}"
echo -e "${D}   Node $(node -v 2>/dev/null) · npm $(npm -v 2>/dev/null)${N}\n"

cd /home/container/app || exit 1
export PORT="${SERVER_PORT}" HOST=0.0.0.0 HOSTNAME=0.0.0.0 NITRO_PORT="${SERVER_PORT}" NITRO_HOST=0.0.0.0

if [[ -d .git && "${AUTO_UPDATE}" == "1" ]]; then
    echo -e "${C}▸ Actualizando desde Git…${N}"
    git pull --ff-only && ok "Código al día" || warn "No se pudo actualizar (se usa el código actual)"
fi

# Plantilla: crea un proyecto nuevo si app/ está vacío o solo tiene la bienvenida de Cinammon
is_empty_app() { [[ -z "$(ls -A)" ]] || { [[ $(ls -A | wc -l) -eq 1 && -f index.html ]] && grep -q 'Cinammon JS Apps' index.html; }; }
if [[ ! -f package.json && -n "${TEMPLATE}" && "${TEMPLATE}" != "ninguna" ]] && is_empty_app; then
    SITE="${SITE_NAME:-Mi proyecto}"
    case "${TEMPLATE}" in
    vitepress)
        echo -e "${C}▸ Creando un proyecto VitePress…${N}"
        rm -f index.html; mkdir -p docs/.vitepress docs/guia docs/public
        cat > package.json <<'CIN_TPL_EOF'
{
  "name": "mi-documentacion",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vitepress dev docs",
    "build": "vitepress build docs",
    "preview": "vitepress preview docs"
  },
  "devDependencies": {
    "vitepress": "^1.6.3"
  }
}
CIN_TPL_EOF
        cat > docs/.vitepress/config.mjs <<CIN_TPL_EOF
import { defineConfig } from 'vitepress'

// Configuración del sitio: https://vitepress.dev/reference/site-config
export default defineConfig({
  lang: 'es',
  title: '${SITE//\'/}',
  description: 'Documentación creada con VitePress y alojada en Cinammon',
  cleanUrls: true,
  outDir: '../dist',
  themeConfig: {
    nav: [
      { text: 'Guía', link: '/guia/' },
      { text: 'VitePress', link: 'https://vitepress.dev/' }
    ],
    sidebar: [
      {
        text: 'Introducción',
        items: [
          { text: 'Primeros pasos', link: '/guia/' },
          { text: 'Escribir páginas', link: '/guia/paginas' },
          { text: 'Publicar cambios', link: '/guia/publicar' }
        ]
      }
    ],
    search: {
      provider: 'local',
      options: {
        translations: {
          button: { buttonText: 'Buscar', buttonAriaLabel: 'Buscar' },
          modal: { noResultsText: 'Sin resultados para', resetButtonTitle: 'Borrar', footer: { selectText: 'abrir', navigateText: 'moverse', closeText: 'cerrar' } }
        }
      }
    },
    outline: { label: 'En esta página' },
    docFooter: { prev: 'Anterior', next: 'Siguiente' },
    darkModeSwitchLabel: 'Apariencia',
    sidebarMenuLabel: 'Menú',
    returnToTopLabel: 'Volver arriba',
    lastUpdatedText: 'Actualizado'
  }
})
CIN_TPL_EOF
        cat > docs/index.md <<CIN_TPL_EOF
---
layout: home

hero:
  name: "${SITE//\"/}"
  text: "Tu documentación, rápida y bonita"
  tagline: Hecha con VitePress y alojada en Cinammon
  actions:
    - theme: brand
      text: Empezar
      link: /guia/
    - theme: alt
      text: Qué es VitePress
      link: https://vitepress.dev/

features:
  - title: Escribe en Markdown
    details: Cada archivo .md de la carpeta docs/ es una página.
  - title: Rápida
    details: Compilada con Vite; carga al instante.
  - title: En tu dominio
    details: Publicada con HTTPS por Cinammon.
---
CIN_TPL_EOF
        cat > docs/guia/index.md <<'CIN_TPL_EOF'
# Primeros pasos

Este proyecto se ha creado solo con la plantilla **VitePress** de Cinammon.

## Dónde está cada cosa

| Archivo | Para qué sirve |
| --- | --- |
| `docs/index.md` | La portada |
| `docs/guia/*.md` | Las páginas de la guía |
| `docs/.vitepress/config.mjs` | Título, menú y barra lateral |
| `docs/public/` | Imágenes y archivos estáticos |

## Editar

Abre **Archivos** en el panel, cambia los `.md` y reinicia el servidor: se vuelve a compilar solo.

::: tip Consejo
Si usas Git, sube este proyecto a un repositorio y ponlo en la variable **Repositorio Git**.
:::
CIN_TPL_EOF
        cat > docs/guia/paginas.md <<'CIN_TPL_EOF'
# Escribir páginas

Crea un archivo `.md` dentro de `docs/` y añádelo a la barra lateral en `docs/.vitepress/config.mjs`.

```md
# Título de la página

Texto en **Markdown**.
```

::: warning Atención
Los nombres de archivo forman la URL: `docs/guia/hola.md` se ve en `/guia/hola`.
:::
CIN_TPL_EOF
        cat > docs/guia/publicar.md <<'CIN_TPL_EOF'
# Publicar cambios

1. Edita tus archivos.
2. Reinicia el servidor desde la **Consola**.
3. Cinammon compila la web y la publica en tu dominio.
CIN_TPL_EOF
        ok "Proyecto VitePress creado en app/" ;;
    vite)
        echo -e "${C}▸ Creando un proyecto Vite…${N}"
        rm -f index.html; mkdir -p src public
        cat > package.json <<'CIN_TPL_EOF'
{
  "name": "mi-app-vite",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview"
  },
  "devDependencies": {
    "vite": "^6.3.5"
  }
}
CIN_TPL_EOF
        cat > index.html <<CIN_TPL_EOF
<!doctype html>
<html lang="es">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>${SITE//</}</title>
  </head>
  <body>
    <div id="app"></div>
    <script type="module" src="/src/main.js"></script>
  </body>
</html>
CIN_TPL_EOF
        cat > src/main.js <<'CIN_TPL_EOF'
import './style.css'

const app = document.querySelector('#app')
let clicks = 0
app.innerHTML = `
  <h1>${document.title}</h1>
  <p>Proyecto Vite creado por Cinammon. Edita <code>src/main.js</code> y reinicia el servidor.</p>
  <button id="counter" type="button">Clics: 0</button>
`
document.querySelector('#counter').addEventListener('click', (e) => {
  e.target.textContent = `Clics: ${++clicks}`
})
CIN_TPL_EOF
        cat > src/style.css <<'CIN_TPL_EOF'
:root { font-family: system-ui, sans-serif; color-scheme: light dark; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; }
#app { max-width: 640px; padding: 2rem; text-align: center; }
h1 { font-size: 2.6rem; margin-bottom: .5rem; }
button { font-size: 1rem; padding: .6rem 1.2rem; border-radius: 8px; border: 1px solid #646cff; background: transparent; cursor: pointer; }
CIN_TPL_EOF
        ok "Proyecto Vite creado en app/" ;;
    *) warn "Plantilla desconocida: ${TEMPLATE}" ;;
    esac
fi

# Sin package.json: web estática tal cual (HTML/CSS/JS subidos a app/)
if [[ ! -f package.json ]]; then
    warn "app/ no tiene package.json: se sirve como web estática."
    exec node /home/container/.cinammon/static.mjs /home/container/app "${SERVER_PORT}"
fi

# Gestor de paquetes según el lockfile del proyecto
PM=npm
if [[ -f pnpm-lock.yaml ]]; then PM=pnpm; elif [[ -f yarn.lock ]]; then PM=yarn; elif [[ -f bun.lockb || -f bun.lock ]]; then PM=bun; fi
if [[ $PM == pnpm || $PM == yarn ]]; then
    export COREPACK_HOME=/home/container/.cinammon/corepack COREPACK_ENABLE_DOWNLOAD_PROMPT=0
    mkdir -p /home/container/.cinammon/bin
    corepack enable --install-directory /home/container/.cinammon/bin >/dev/null 2>&1 && export PATH="/home/container/.cinammon/bin:$PATH" || { warn "corepack no disponible: se usa npm"; PM=npm; }
fi
if [[ $PM == bun ]] && ! command -v bun >/dev/null; then warn "bun no está en la imagen: se usa npm"; PM=npm; fi

# Dependencias: solo si cambió package.json o el lockfile
HASH=$(cat package.json package-lock.json pnpm-lock.yaml yarn.lock bun.lock 2>/dev/null | md5sum | cut -d' ' -f1)
if [[ ! -d node_modules || "$(cat /home/container/.cinammon/deps.hash 2>/dev/null)" != "$HASH" ]]; then
    echo -e "${C}▸ Instalando dependencias con ${PM}…${N}"
    case $PM in
        pnpm) pnpm install --frozen-lockfile=false ;;
        yarn) yarn install ;;
        bun)  bun install ;;
        *)    if [[ -f package-lock.json ]]; then npm ci --no-audit --no-fund || npm install --no-audit --no-fund; else npm install --no-audit --no-fund; fi ;;
    esac || { fail "Falló la instalación de dependencias"; exit 1; }
    echo "$HASH" > /home/container/.cinammon/deps.hash
    ok "Dependencias listas"
fi
[[ -n "${NODE_PACKAGES}" ]] && { echo -e "${C}▸ Paquetes extra: ${NODE_PACKAGES}${N}"; npm install --no-audit --no-fund ${NODE_PACKAGES}; }

run() { if [[ $PM == npm ]]; then npm run "$@"; else $PM run "$@"; fi; }
has_script() { node -e "process.exit(require('./package.json').scripts?.['$1'] ? 0 : 1)" 2>/dev/null; }
# Comando por defecto sin script "build" (p. ej. VitePress usa docs:build): se busca el adecuado
if [[ "${BUILD_CMD}" == "npm run build" ]] && ! has_script build; then
    for s in docs:build build:prod generate; do
        if has_script "$s"; then BUILD_CMD="npm run $s"; warn "No hay script \"build\": se usa \"$s\""; break; fi
    done
fi
OUT="${OUTPUT_DIR:-dist}"
# Carpeta compilada: la configurada o, si no existe, la habitual de cada herramienta
find_out() {
    [[ -f "$OUT/index.html" ]] && return 0
    for d in dist build out docs/.vitepress/dist .vitepress/dist src/.vitepress/dist .output/public docs/dist; do
        if [[ -f "$d/index.html" ]]; then warn "No hay ${OUT}/index.html: se publica ${d}/"; OUT="$d"; return 0; fi
    done
    return 1
}

if [[ "${APP_MODE}" == "node" ]]; then
    # Servidor Node: Next.js, Nuxt, Astro SSR, SvelteKit (adapter-node), Remix, Express…
    if [[ -n "${BUILD_CMD}" ]] && grep -q '"build"' package.json; then
        echo -e "${C}▸ Compilando (${BUILD_CMD})…${N}"
        NODE_ENV=production bash -c "${BUILD_CMD}" || { fail "La compilación falló"; exit 1; }
        ok "Compilación terminada"
    fi
    echo -e "\n${G}  ● Web en línea${N} ${D}(arrancando: ${START_CMD:-npm start} en el puerto ${SERVER_PORT})${N}\n"
    NODE_ENV=production exec bash -c "${START_CMD:-npm start}"
fi

# Web compilada (Vite, React, Vue, Svelte, Astro estático…): se compila si hay cambios
needs_build() {
    find_out || return 0
    [[ -n "$(find . -path ./node_modules -prune -o -path "./$OUT" -prune -o -path ./.git -prune -o -type f -newer "$OUT/index.html" -print -quit)" ]]
}
if [[ -n "${BUILD_CMD}" ]] && needs_build; then
    echo -e "${C}▸ Compilando (${BUILD_CMD})…${N}"
    bash -c "${BUILD_CMD}" || { fail "La compilación falló: revisa el error de arriba"; exit 1; }
    ok "Compilación terminada"
else
    ok "Sin cambios desde la última compilación"
fi
if ! find_out; then
    fail "No encuentro la web compilada (${OUT}/index.html). Revisa «Carpeta compilada»: Vite usa dist, Create React App build, VitePress docs/.vitepress/dist."
    exit 1
fi
exec node /home/container/.cinammon/static.mjs "/home/container/app/${OUT}" "${SERVER_PORT}"
CIN_START_EOF
chmod +x start.sh

# ── Proyecto: Git o página de bienvenida ──
cd /mnt/server/app
is_welcome() { [[ -f index.html ]] && grep -q 'Cinammon JS Apps' index.html && [[ $(ls -A | wc -l) -eq 1 ]]; }

if [[ -n "${GIT_ADDRESS}" ]]; then
    [[ ${GIT_ADDRESS} != *.git ]] && GIT_ADDRESS=${GIT_ADDRESS}.git
    if [[ -n "${USERNAME}" && -n "${ACCESS_TOKEN}" ]]; then
        GIT_ADDRESS="https://${USERNAME}:${ACCESS_TOKEN}@$(echo ${GIT_ADDRESS} | cut -d/ -f3-)"
    fi
    if [[ -d .git ]]; then
        echo "▸ Actualizando el repositorio…"; git pull
    elif [[ -z "$(ls -A .)" ]] || is_welcome; then
        rm -f index.html
        echo "▸ Clonando el repositorio…"
        if [[ -z "${BRANCH}" ]]; then git clone ${GIT_ADDRESS} .; else git clone --single-branch --branch ${BRANCH} ${GIT_ADDRESS} .; fi
        rm -f /mnt/server/.cinammon/deps.hash
    else
        echo "⚠ app/ ya tiene archivos y no es un repositorio Git: no se clona para no borrar nada."
    fi
elif [[ -z "$(ls -A .)" ]]; then
cat > index.html <<'CIN_INDEX_EOF'
