body:before{content:"";position:fixed;inset:0;background:radial-gradient(600px 400px at 15% 10%,rgba(168,85,247,.14),transparent 60%),radial-gradient(600px 400px at 85% 90%,rgba(255,45,149,.12),transparent 60%),radial-gradient(circle,rgba(255,255,255,.07) 1px,transparent 1px) 0 0/24px 24px;pointer-events:none}
